 private static int row(StringBuilder s,int[] x,int y,int h,String text,boolean green){text=safe(text);box(s,x[0],y-h,x[6]-x[0],h,green);int tx=green?x[0]+Math.max(6,(x[6]-x[0]-text.length()*8)/2):x[0]+6;text(s,tx,y-h+6,text,green?16:10,green);return y-h;}
