 private static String m(double value){return Money.text(value);}private static String m(Double value){return Money.text(value==null?0:value);}private static String safe(String x){return x==null?"":x;}private static String escape(String x){return safe(x).replace("\\","\\\\").replace("(","\\(").replace(")","\\)").replaceAll("[^\\x20-\\x7E]","");}private static String fileSafe(String x){return(x==null?"Employee":x).replaceAll("[^a-zA-Z0-9_-]","_");}static final class Logo{final byte[] data;final int width,height;Logo(byte[] data,int width,int height){this.data=data;this.width=width;this.height=height;}static Logo load(){try{String path=CompanyDetailsStore.logoPath();if(path==null||path.isEmpty())return null;File file=new File(path);if(!file.isFile())return null;BufferedImage source=ImageIO.read(file);if(source==null)return null;BufferedImage image=new BufferedImage(source.getWidth(),source.getHeight(),BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D graphics=image.createGraphics();graphics.drawImage(source,0,0,null);graphics.dispose();ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(!ImageIO.write(image,"jpg",bytes))return null;return new Logo(bytes.toByteArray(),image.getWidth(),image.getHeight());}catch(Exception ignored){return null;}}String draw(){return "q 34 0 0 34 28 732 cm /Logo Do Q\n";}}private PayslipPDF(){}
